package com.quincaisoft.finance.application;
import com.quincaisoft.finance.api.*;import com.quincaisoft.finance.infrastructure.*;import com.quincaisoft.company.api.CompanyService;import com.quincaisoft.shared.*;import jakarta.persistence.*;import org.springframework.stereotype.Service;import tools.jackson.databind.json.JsonMapper;import java.util.*;import java.security.*;import java.nio.charset.StandardCharsets;import java.util.function.Supplier;
@Service public class DefaultPeriodService implements PeriodService {
 private final EntityManager em;private final ScopedTransactions tx;private final CompanyService companies;private final List<PeriodCloseGuard> guards;private final JsonMapper json;
 public DefaultPeriodService(EntityManager em,ScopedTransactions tx,CompanyService companies,List<PeriodCloseGuard> guards,JsonMapper json){this.em=em;this.tx=tx;this.companies=companies;this.guards=guards;this.json=json;}
 private void reason(String s){if(s==null||s.trim().length()<3||s.length()>2000)throw new IllegalArgumentException("Reason required");}
 private FinancialPeriodEntity period(UUID id){var s=TenantContext.current();var r=em.find(FinancialPeriodEntity.class,new FinancialPeriodEntity.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(r==null)throw new NoSuchElementException("Financial period not found");return r;}
 private Period view(FinancialPeriodEntity r){return new Period(r.id,r.startDate,r.endDate,r.status,r.version);}private Request view(PeriodRequestEntity r){return new Request(r.id,r.periodId,r.action,r.status,r.requestedBy,r.decidedBy,r.version,r.reason,r.decisionReason);}
 private <T>T once(UUID op,String material,Class<T> type,Supplier<T> action){if(op==null)throw new IllegalArgumentException("Operation required");return tx.execute(()->{companies.requireSingleBranchCompany();var s=TenantContext.current();String hash=hash(material);em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k",s.tenantId()+":"+op).getSingleResult();var rows=em.createNativeQuery("select request_hash,company_id,branch_id,response_json::text from idempotency_result where tenant_id=:t and operation_id=:o").setParameter("t",s.tenantId()).setParameter("o",op).getResultList();if(!rows.isEmpty()){Object[] row=(Object[])rows.getFirst();if(!hash.equals(row[0])||!s.companyId().equals(row[1])||!s.branchId().equals(row[2]))throw new IllegalStateException("Operation conflict");FinanceReplayEvidence.requireActor(em,op,"PeriodChanged.v1",true);if(row[3]==null)throw new IllegalStateException("Committed operation response expired");return json.readValue((String)row[3],type);}T result=action.get();UUID id=result instanceof Period p?p.id():((Request)result).id();em.createNativeQuery("insert into idempotency_result(tenant_id,operation_id,company_id,branch_id,request_hash,source_type,source_id,response_json)values(:t,:o,:c,:b,:h,'PERIOD_COMMAND',:i,cast(:r as jsonb))").setParameter("t",s.tenantId()).setParameter("o",op).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("h",hash).setParameter("i",id).setParameter("r",json.writeValueAsString(result)).executeUpdate();em.createNativeQuery("insert into outbox_event(tenant_id,id,company_id,branch_id,operation_id,event_type,aggregate_type,aggregate_id,payload)values(:t,:i,:c,:b,:o,'PeriodChanged.v1','period',:a,cast(:p as jsonb))").setParameter("t",s.tenantId()).setParameter("i",UUID.randomUUID()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",op).setParameter("a",id).setParameter("p",eventPayload(result,s.actorId())).executeUpdate();return result;});}
 public List<Period> list(){return tx.execute(()->em.createQuery("select r from FinancialPeriodEntity r order by r.startDate desc",FinancialPeriodEntity.class).setMaxResults(200).getResultList().stream().map(this::view).toList());}
 public List<Request> requests(){return tx.execute(()->em.createQuery("select r from PeriodRequestEntity r order by r.id",PeriodRequestEntity.class).setMaxResults(200).getResultList().stream().map(this::view).toList());}
 public Period create(Create p){reason(p.reason());if(p.startDate()==null||p.endDate()==null||p.startDate().isAfter(p.endDate()))throw new IllegalArgumentException("Valid period date range required");return once(p.operationId(),"CREATE|"+p,Period.class,()->{var s=TenantContext.current();em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k","period-create:"+s.tenantId()+":"+s.companyId()).getSingleResult();if(!em.createQuery("select r from FinancialPeriodEntity r where r.startDate<=:end and r.endDate>=:start",FinancialPeriodEntity.class).setParameter("end",p.endDate()).setParameter("start",p.startDate()).getResultList().isEmpty())throw new IllegalArgumentException("Period overlaps existing date range");var r=new FinancialPeriodEntity();r.tenantId=s.tenantId();r.companyId=s.companyId();r.id=UUID.randomUUID();r.startDate=p.startDate();r.endDate=p.endDate();r.status="Open";em.persist(r);em.flush();return view(r);});}
 public Request request(UUID id,String action,Command p){reason(p.reason());if(!Set.of("CLOSE","REOPEN").contains(action))throw new IllegalArgumentException("Supported period action required");return once(p.operationId(),action+"|"+id+"|"+p,Request.class,()->{var period=period(id);if(period.version!=p.version())throw new RevisionConflict("Period changed");if(!period.status.equals(action.equals("CLOSE")?"Open":"Closed"))throw new IllegalStateException("Period state does not allow requested change");var s=TenantContext.current();var r=new PeriodRequestEntity();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.id=UUID.randomUUID();r.periodId=id;r.action=action;r.status="REQUESTED";r.requestedBy=s.actorId();r.periodVersion=period.version;r.reason=p.reason();em.persist(r);em.flush();return view(r);});}
 public Request decide(UUID id,boolean approve,Command p){reason(p.reason());return once(p.operationId(),"DECIDE|"+id+"|"+approve+"|"+p,Request.class,()->{var s=TenantContext.current();var r=em.find(PeriodRequestEntity.class,new PeriodRequestEntity.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(r==null)throw new NoSuchElementException("Close/reopen request not found");if(r.version!=p.version())throw new RevisionConflict("Request changed");if(!r.status.equals("REQUESTED"))throw new IllegalStateException("Pending period request required");if(r.requestedBy.equals(s.actorId()))throw new IllegalArgumentException("Independent period approver required");if(approve){var period=period(r.periodId);if(period.version!=r.periodVersion)throw new RevisionConflict("Period changed since request");if(r.action.equals("CLOSE")){if(!period.status.equals("Open"))throw new IllegalStateException("Open period required");if(!guards.stream().map(PeriodCloseGuard::domain).collect(java.util.stream.Collectors.toSet()).containsAll(Set.of("cash","providers","expenses","returns")))throw new IllegalStateException("Required period close guards not installed");for(var guard:guards)guard.verifyCanClose(period.startDate,period.endDate);r.status="APPROVED";r.decidedBy=s.actorId();r.decisionReason=p.reason();em.flush();period.status="Closed";}else{if(!period.status.equals("Closed"))throw new IllegalStateException("Closed period required");r.status="APPROVED";r.decidedBy=s.actorId();r.decisionReason=p.reason();em.flush();period.status="Open";}}r.status=approve?"APPROVED":"REJECTED";r.decidedBy=s.actorId();r.decisionReason=p.reason();em.flush();return view(r);});}
 private String eventPayload(Object result,UUID actor){var payload=new LinkedHashMap<String,Object>(json.readValue(json.writeValueAsString(result),Map.class));payload.put("actorId",actor.toString());return json.writeValueAsString(payload);}
 private static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
